   "professor": "김소영",
   "evaluation": "중간고사 30%, 기말고사 30%, 발표/과제 20%, 출석 20%",
   "textbook": "(주교재) 정형, 사진 통계와 함께 읽는 일본, 일본인, 일본문화[전면 개정판](3rd Edition), 다락원. (참고교재) 이경수, 사진으로 보고 가장 쉽게 읽는 일본문화[개정판], 시사일본어사.",
